    "content": "新华社华盛顿8月17日电（记者黄强 徐剑梅）美国总统特朗普17日在白宫对媒体称，朝鲜领导人金正恩已回应他提出的“对话”请求，但他没有透露回应的内容。 特朗普称，他所做的“一切都是为了让局势更加安全”，并称“我了解他（金正恩），他也了解我。我与他相处融洽”。 特朗普还说，韩国在伊朗问题上不同意协助美国，这令他感到不满，并促使他决定缩减美韩联合军事演习规模。 特朗普16日在社交媒体发文说，他已要求国防部大幅缩减美国与韩国的联合军演规模。他称，这些军演“耗资巨大”，其中很大一部分由美国负担，同时对朝鲜释放出“完全不恰当和…"
