    "content": "新华社华盛顿8月17日电（记者黄强 徐剑梅）美国总统特朗普17日在白宫对媒体称，伊朗想要达成协议，但“不会达成我认为必要的那种协议”。 特朗普是在回答有关美伊谈判进展的提问时作上述表态的。他没有透露谈判进展情况，只是强调“伊朗不能拥有核武器”。 当被问及美国是否打算延长与伊朗达成的谅解备忘录时，特朗普给出了否定的回答。8月17日，美国和伊朗谅解备忘录所设定的60天谈判窗口期期满。双方6月中旬远程签署这一备忘录，承诺在60天内进行谈判并达成最终协议。 特朗普还称，美国正通过封锁“完全”控制着霍尔木兹海峡，而且“我们每…"
