    "description": "总台记者获悉，当地时间8月17日，国际足联确认与其首席运营官凯文·拉穆尔之间的工作关系已于当天结束。 拉穆尔此前曾公开批评国际足联主席因凡蒂诺“将世界杯等赛事部分股权出售给投资者”的计划，称相关计划是“个人项目”并缺乏透明度。国际足联主席高级顾问卡洛斯·科尔代罗也因反对该计划而辞职。",
    "content": "总台记者获悉，当地时间8月17日，国际足联确认与其首席运营官凯文·拉穆尔之间的工作关系已于当天结束。 拉穆尔此前曾公开批评国际足联主席因凡蒂诺“将世界杯等赛事部分股权出售给投资者”的计划，称相关计划是“个人项目”并缺乏透明度。国际足联主席高级顾问卡洛斯·科尔代罗也因反对该计划而辞职。"
