    "content": "当地时间8月17日，一名伊朗高级官员在接受采访时说，伊朗已为美国全面履行伊美谅解备忘录设定了数周的最后期限，伊朗不会无限期等待美国继续实施海上封锁。 该官员表示，由于“与美国达成永久停战协议的努力陷入僵局”，伊朗已决定将其政策“从防御性转向全面进攻性”。 该官员说，如果外交努力失败，“伊朗人已准备好将升级霍尔木兹海峡及（中东）地区的紧张局势。伊朗的时间表将通过调解国传递给美国。” 美国和伊朗6月17日公布谅解备忘录正式文本，其中第三条内容是：美国与伊朗承诺在最多60天内进行谈判并达成最终协议。8月17日，谅解备忘录…"
