    "content": "新华社耶路撒冷8月17日电（记者陈君清 冯国芮）据以色列多家媒体17日报道，美国总统特朗普的女婿库什纳以及加沙地带“和平委员会”成员当天在耶路撒冷与以色列总理内塔尼亚胡举行会晤，以期进一步推进所谓“加沙和平计划”。 以总理办公室在会后发表声明说，内塔尼亚胡与“和平委员会”讨论后，同意成立两个工作组，一个负责巴勒斯坦伊斯兰抵抗运动（哈马斯）的裁军和非军事化，双方认为这项工作须在加沙重建工作开始前尽快完成；另一个将重点关注加沙地带的卫生、清洁水源等问题。 以色列《国土报》报道说，当天会晤“成果”还包括允许以色列“暂时”…"
