    "content": "17/08/2026 - 17:35 美国总统特朗普宣布“大幅减少”参与周一启动的美韩年度联合军演，除了提到他与金正恩的“非常良好的关系”之外，还批评首尔拒绝参与美国推动的伊朗无核化行动。 特朗普在其真相社交平台（Truth Social）的帖文中抨击这些演习“耗资巨大”，并称其向朝鲜“发出了完全“不恰当且具有敌意的信号”。 唐纳德-特朗普特别提到韩国拒绝参与美国针对伊朗的军事行动，并以此证明美国缩减联合军演规模的合理性。 “不，谢谢！” 他写道：“虽然这似乎没什么关系，但我最近曾询问韩国总统，他们是否愿意加入我们…"
