    "description": "记者17日从国家市场监督管理总局了解到，“十四五”时期，市场监管部门部署开展滥用行政权力排除、限制竞争执法相关专项行动，依法查处案件290件，促进优化营商环境，服务全国统一大市场建设。 新华社北京8月17日电（记者赵怡宁）记者17日从国家市场监督管理总局了解到，“十四五”时期，市场监管部门部署开展滥用行政权力排除、限制竞争执法相关专项行动，依法查处案件290件，促进优化营商环境，服务全国统一大市场建设。 据了解，“十四五”时期，市场监管…",
    "content": "记者17日从国家市场监督管理总局了解到，“十四五”时期，市场监管部门部署开展滥用行政权力排除、限制竞争执法相关专项行动，依法查处案件290件，促进优化营商环境，服务全国统一大市场建设。 新华社北京8月17日电（记者赵怡宁）记者17日从国家市场监督管理总局了解到，“十四五”时期，市场监管部门部署开展滥用行政权力排除、限制竞争执法相关专项行动，依法查处案件290件，促进优化营商环境，服务全国统一大市场建设。 据了解，“十四五”时期，市场监管部门执法力度持续加大，年均办结案件提升至58件，涵盖城市管理、招标采购、工程建筑…"
