    "pub_date": "2026-08-17 23:08:16",
    "author": "邵海军",
    "description": "新华社海牙8月17日电（记者邵海军 李弘）荷兰国家公共卫生与环境研究所17日通报，近日从一名献血者的血液内检测出西尼罗病毒，这是该国2020年以来首例确诊的本土感染病例。 通报说，这名感染者来自乌特勒支省，目前症状轻微，近期无出国旅行史，因此很可能是在荷兰境内感染。据荷兰媒体报道，在这名感染者被检测出感染病毒前，其血液已被输注给一名受血者。 荷兰各地近期在马、鸟体内检测出西尼罗病毒。荷兰卫生机构将病例出现地列为血液安全风险地区，全面筛查…",
    "content": "新华社海牙8月17日电（记者邵海军 李弘）荷兰国家公共卫生与环境研究所17日通报，近日从一名献血者的血液内检测出西尼罗病毒，这是该国2020年以来首例确诊的本土感染病例。 通报说，这名感染者来自乌特勒支省，目前症状轻微，近期无出国旅行史，因此很可能是在荷兰境内感染。据荷兰媒体报道，在这名感染者被检测出感染病毒前，其血液已被输注给一名受血者。 荷兰各地近期在马、鸟体内检测出西尼罗病毒。荷兰卫生机构将病例出现地列为血液安全风险地区，全面筛查这些地区献血者的血液。 荷兰国家公共卫生与环境研究所说，在荷兰感染西尼罗病毒的几…"
