    "title": "多部门发文进一步保障农业灌溉用水安全",
    "link": "http://www.news.cn/20260817/ad40bf9e357847bba8c9aba1d1f41a0d/c.html",
    "pub_date": "2026-08-17 23:05:04",
    "author": "高敬",
