    "content": "生态环境部会同工业和信息化部、农业农村部等部门近日联合印发通知，进一步加强工业、畜禽养殖等企业污水污染风险防范，保障农业灌溉用水安全。 新华社北京8月17日电（记者高敬）生态环境部会同工业和信息化部、农业农村部等部门近日联合印发通知，进一步加强工业、畜禽养殖等企业污水污染风险防范，保障农业灌溉用水安全。 生态环境部水生态环境司有关负责人17日介绍，近年来，一些工业企业及园区、畜禽养殖场等与农田相邻，污水排放管控不到位，农业灌溉用水安全隐患不容忽视。此次印发的通知以保障农业灌溉用水安全为核心，以源头预防、过程把控、末…"
