    "content": "8月17日晚，芯原股份（688521）披露了2026年上半年业绩。报告期内，公司实现营业收入18.64亿元，同比增长91.37%。尽管营收出现大幅增长，但上半年芯原股份的净亏损却进一步扩大，净利润为亏损6.12亿元，去年全年亏损为5.28亿元，去年同期为亏损3.2亿元，扣非后净利润亏损6.22亿元。 2026 年上半年，芯原股份综合毛利率为31.34%， 较去年同期下降11.98个百分点， 主要由于收入结构变化等因素导致。所谓收入结构变化主要是指芯原股份的量产服务收入出现大幅增长，但这块业务毛利率比较低，拖累了公司…"
