    "description": "两组旗帜，一场硬仗。 在河南周口贾鲁河溃口抢险一线，入职仅一年的中国安能贵阳基地青年队员周廷锋，与合肥救援基地的队友并肩值守最危险的作业点位，依靠标准旗语不间断指挥车流、抢运石料，保障石料顺畅转运。 十几个小时，依靠不停挥动的红绿旗帜，上百车石料从周廷锋和队友指挥的位置精准投下。 从溃口挥到合龙，从合龙挥到加固。周廷锋说，守到最后一刻才算数。 记者：翟濯 杨静 画面来源：中国安能集团 新华社音视频部制作",
    "content": "两组旗帜，一场硬仗。 在河南周口贾鲁河溃口抢险一线，入职仅一年的中国安能贵阳基地青年队员周廷锋，与合肥救援基地的队友并肩值守最危险的作业点位，依靠标准旗语不间断指挥车流、抢运石料，保障石料顺畅转运。 十几个小时，依靠不停挥动的红绿旗帜，上百车石料从周廷锋和队友指挥的位置精准投下。 从溃口挥到合龙，从合龙挥到加固。周廷锋说，守到最后一刻才算数。 记者：翟濯 杨静 画面来源：中国安能集团 新华社音视频部制作"
