    "content": "新华社首尔8月17日电（记者黄昕欣）韩国执政党共同民主党17日在大田市举行全国党员大会，前国务总理金民锡当选新一任党首。 共同民主党党首任期两年。金民锡将掌握2028年韩国国会议员选举共同民主党候选人提名权，对李在明政府执政及执政党内部权力格局具有重要影响，其影响力还可能延续至下一届韩国总统选举前的执政阵营力量重组。 韩联社报道称，在总统李在明支持率不断下滑之际，金民锡肩负重任，承担着增强党政协作施政、弥合全党分歧的关键任务。 李在明当天在大会选举前发表视频致辞，号召共同民主党团结一致。 金民锡1964年出生于韩国…"
