    "content": "新华社北京/首尔8月17日电（记者刘品然 张粲）韩国和美国军方17日开始举行代号为“乙支自由之盾”的联合军演。与此同时，美国总统特朗普却称军演向朝鲜释放“敌对信号”，他已要求“大幅缩减”军演规模。他还暗批韩国不配合美国对伊朗政策。 分析人士认为，特朗普宣布调整军演规模并非有意缓和地区局势，更多是寻求外界关注和外交加分。此举是美国现任政府胁迫盟友的惯用套路，暴露出其在朝鲜半岛和伊朗问题上陷入政策僵局的挫败感。 军演规模尚未调整？ “乙支自由之盾”是韩美年度例行联合军演，通常在每年八九月举行。据两国军方消息，今年的演习…"
