    "title": "广东高院出台15条举措护航绿色低碳发展",
    "link": "https://www.chinanews.com.cn/gn/2026/08-17/10679322.shtml",
    "pub_date": "2026-08-17 21:53:08",
    "author": "",
    "description": "中新网广州8月17日电 (方伟彬 马卓尔 王骁)广东省高级人民法院17日出台《关于司法服务保障绿色低碳发展的工作意见》(下称《意见》)，围绕理念引领、审判履职、产业护航、机制建设四个维度推出15条举措，将生态环境法典精神融入司法实践，为经济社会发展全面绿色转型提供全链条司法保障。",
