    "content": "“这是吉利汽车去家族化的宣言，标志着吉利汽车已经从创始人驱动的创业期和发展期，迈向了由制度和团队驱动的成长期。”8月17日，在吉利汽车控股有限公司（吉利汽车，00175.HK）业绩说明会上，针对李书福卸任吉利汽车董事会主席一事，吉利汽车董事会副主席桂生悦回应称。 他认为，这意味着吉利汽车将不再依赖个人魅力和权威，而是依赖组织系统和人才梯队。而吉利汽车未来的治理将更加透明，决策将更加专业，管理更加科学。 桂生悦还补充说，这一举措对内部人才而言，是“天花板被打破的信号”，将极大程度激励全体员工的奋斗热情，让企业能够为广…"
