    "content": "中文维基是最大的非官方中文百科，它通过公开讨论决定条目的存废，编辑们引用政策进行辩论，最终由一名编辑审阅整个讨论并对条目最终命运做出具有约束力的决定。但究竟是谁参与了讨论？决策权的集中程度如何？哪些议题会引发争议？又是什么逻辑驱动最终结果？纽约城市大学的两名研究人员分析了 2020-2024 年间中文维基 47,030 个条目存废讨论案例，发现虽然每年有数百名编辑参与讨论，但最终决定权集中在少数人手中，而且这些决定者的人数还在不断减少，其中一人在一年内做出了 89.9% 的决定。研究还发现，虽然简体中文用户人数是繁…"
