    "pub_date": "2026-08-17 21:20:08",
    "author": "weiyunjun",
    "description": "如题，主要是想买新玩具了。 之前我的全新的游戏机基本都是日本亚马逊买的，现在日本亚马逊只有日语特供版了，没有国际版。看了一下淘宝和拼多多，发现评论区不少反馈有各种瑕疵的，有点担心。 其实还是有点想玩 NS2 版的异度神剑和火焰纹章的，前者 NS 版太糊，后者新作 NS2 独占。 下个月官宣涨价，到时候价格可能还会贵一些，所以我现在有点纠结。当然，如果渠道不好，很容易买到瑕疵机器，还是算了。 V 友可以给点建议吗？感谢~",
    "content": "如题，主要是想买新玩具了。 之前我的全新的游戏机基本都是日本亚马逊买的，现在日本亚马逊只有日语特供版了，没有国际版。看了一下淘宝和拼多多，发现评论区不少反馈有各种瑕疵的，有点担心。 其实还是有点想玩 NS2 版的异度神剑和火焰纹章的，前者 NS 版太糊，后者新作 NS2 独占。 下个月官宣涨价，到时候价格可能还会贵一些，所以我现在有点纠结。当然，如果渠道不好，很容易买到瑕疵机器，还是算了。 V 友可以给点建议吗？感谢~"
