    "description": "新华社北京8月17日电（记者刘诗平）中国气象科学研究院最新完成的一项研究显示，2002年以来，华北极端暴雨增多、增强，台风是重要的推手。 中国气象科学研究院研究员李英团队开展的这项研究，系统梳理和分析了1977至2023年华北地区428个气象站每年6至9月的逐日降雨数据。研究显示，1977至2002年，北方雨季降水和区域性极端降水频率变化不明显；2003至2023年，华北雨季总雨量呈增加趋势，其中区域性的极端暴雨明显增多、增强。 “降水…",
    "content": "新华社北京8月17日电（记者刘诗平）中国气象科学研究院最新完成的一项研究显示，2002年以来，华北极端暴雨增多、增强，台风是重要的推手。 中国气象科学研究院研究员李英团队开展的这项研究，系统梳理和分析了1977至2023年华北地区428个气象站每年6至9月的逐日降雨数据。研究显示，1977至2002年，北方雨季降水和区域性极端降水频率变化不明显；2003至2023年，华北雨季总雨量呈增加趋势，其中区域性的极端暴雨明显增多、增强。 “降水变化的转折点是2002年。”李英说，随着全球变暖，我国台风登陆地点呈北移趋势，影…"
