    "content": "新华社北京8月17日电 记者手记：守护孩子脊柱健康 顾天成、尹硕韩 12岁的涵涵在康复师指导下缓缓吸气，努力将气体“送”进胸廓凹陷的一侧，而后针对性练习体操动作。父亲孙先生坐在一旁，不断记下康复师的指导内容。 涵涵一家专门从山东德州赶来，奔赴一场特殊的“守护”——2026年北京儿童医院少年儿童脊柱健康夏令营。 “去年学校体检提示孩子可能有脊柱侧弯，家人以为只是坐姿问题。今年暑假，高低肩愈发明显，确诊为‘S型双弯’。”孙先生说。 涵涵的经历并非个例。最新流行病学调查数据显示，我国儿童青少年脊柱侧弯发病率约为1%至3%…"
